// OmniFlow batch 220 - WhatsApp (laptop connector) media capture: customer voice notes + photos reach the Control Plane.
//
// Run from the WEBSITE repo root (the bot root - the folder that contains run_channel.py, src/ and OmniFlow-Control-Plane/):
//     node wa_media_capture_220.mjs
// Safe to run twice (second run says "already"). Old copies are kept as *.pre_220.bak.
//
// What it does:
//  * Laptop: src/whatsapp.py (photo bubbles detected - the caption is the text, never the time label;
//    in-memory photo copy by message id; stickers / videos / quoted / link previews skipped),
//    src/channels/whatsapp_web.py (image events + capture_image), run_channel.py (voice note copy before the
//    temp file is deleted; CP speech-to-text takes over if local transcription fails; caption-less photos go to
//    the CP only), src/control_plane_bridge.py (media + exact message id; a file travels alone with its own
//    timeout; 2 failed uploads -> text only; bounded offline backlog).
//  * Control Plane: portal_media_ai.py - a voice note the laptop already transcribed is stored, not transcribed twice.
//  * Tests: tools/cp-testrig/test_wa_media_capture.py (90 checks), tools/web-tests/wa_media_capture_e2e.py (real Playwright).
//
// Laptop .env (optional, defaults shown): OMNIFLOW_WA_MEDIA_CAPTURE=on  OMNIFLOW_WA_MEDIA_MAX_BYTES=3000000
//   OMNIFLOW_CP_MEDIA_TIMEOUT_SECONDS=30  OMNIFLOW_CP_MEDIA_RETRIES=2  OMNIFLOW_CP_MEDIA_BACKLOG=3
// After running: restart the WhatsApp worker (run_channel.py / run_all_channels.py) so the new code loads.
import fs from "fs";
import { createRequire } from "module";
const require = createRequire(import.meta.url);
const BACKUP_TAG = ".pre_220.bak";
let applied = 0, already = 0, warnings = 0;
